$ErrorActionPreference = "Stop"

$root = "C:\Users\yildi\Desktop\3Dcad"
$detector = Join-Path $root "src\cad\wall_detector.py"

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $root ("backups\wall_fast_overlap_owner_" + $stamp)
New-Item -ItemType Directory -Force -Path $backup | Out-Null

if (!(Test-Path $detector)) {
    throw "wall_detector.py not found."
}

Copy-Item $detector (Join-Path $backup "wall_detector.py") -Force

$tmpPy = Join-Path $env:TEMP "wall_fast_overlap_owner_fix.py"
[IO.File]::WriteAllBytes(
    $tmpPy,
    [Convert]::FromBase64String("")
)

& py -3.12 $tmpPy

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Patch failed. Previous wall_detector.py restored."
}

$env:PYTHONPATH = Join-Path $root "src"
$env:PYTHONUTF8 = "1"
$env:PYTHONIOENCODING = "utf-8"

& py -3.12 -m py_compile $detector

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Compile failed. Previous wall_detector.py restored."
}

& py -3.12 -c "from cad.wall_detector import detect_walls, WallCandidate; print('FAST OVERLAP OWNER PASS')"

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Import failed. Previous wall_detector.py restored."
}

Write-Host ""
Write-Host "FAST OVERLAP OWNER FIX INSTALLED" -ForegroundColor Green
Write-Host "Only exact same-layer collinear contained 2-point lines are handled."
Write-Host "The shorter overlapping line cannot own wall continuity; its longer containing line is selected instead."
Write-Host "The overlap map is calculated once, so the previous repeated full-drawing scan is not used."
Write-Host "Existing door, window, layer and exclusion rules remain unchanged."
Write-Host ("Backup: " + $backup)
